@isTest private class CurrentBaseDatacloudDtoDeterministic001Test {
    @isTest static void datacloudDtoDeterministic001Witness() {
        Datacloud.AdditionalInformationMap aim = new Datacloud.AdditionalInformationMap();
        System.assertNotEquals(null, aim);
        aim.name = 'Country';
        aim.value = 'US';
        System.assertEquals('Country', aim.name);
        System.assertEquals('US', aim.value);
        System.assertEquals('Country', aim.getName());
        System.assertEquals('US', aim.getValue());
        System.assertEquals(true, aim.equals(aim));
        System.assertNotEquals(null, aim.hashCode());
        System.assertNotEquals(null, aim.toString());

        Datacloud.DuplicateResult dr = new Datacloud.DuplicateResult();
        System.assertNotEquals(null, dr);
        dr.allowsave = true;
        dr.duplicaterule = 'Rule1';
        dr.duplicateruleentitytype = 'Account';
        dr.errormessage = 'duplicate detected';
        dr.matchresults = new List<Datacloud.MatchResult>();
        System.assertEquals(true, dr.allowsave);
        System.assertEquals('Rule1', dr.duplicaterule);
        System.assertEquals('Account', dr.duplicateruleentitytype);
        System.assertEquals('duplicate detected', dr.errormessage);
        System.assertEquals(true, dr.isAllowSave());
        System.assertEquals('Rule1', dr.getDuplicateRule());
        System.assertEquals('Account', dr.getDuplicateRuleEntityType());
        System.assertEquals('duplicate detected', dr.getErrorMessage());
        System.assertEquals(0, dr.matchresults.size());
        System.assertEquals(true, dr.getMatchResults() == null || dr.getMatchResults().isEmpty());
        System.assertEquals(true, dr.equals(dr));
        System.assertNotEquals(null, dr.hashCode());
        System.assertNotEquals(null, dr.toString());

        Datacloud.FieldDiff fd = new Datacloud.FieldDiff();
        System.assertNotEquals(null, fd);
        fd.name = 'Name';
        fd.difference = 'Changed';
        System.assertEquals('Name', fd.name);
        System.assertEquals('Changed', fd.difference);
        System.assertEquals('Name', fd.getName());
        System.assertEquals('Changed', fd.getDifference());
        System.assertEquals(true, fd.equals(fd));
        System.assertNotEquals(null, fd.hashCode());
        System.assertNotEquals(null, fd.toString());

        Datacloud.FieldDifferenceType fdt = new Datacloud.FieldDifferenceType();
        System.assertNotEquals(null, fdt);
        fdt.name = 'SAME';
        System.assertEquals('SAME', fdt.name);
        System.assertEquals('SAME', fdt.getName());
        System.assertEquals(true, fdt.equals(fdt));
        System.assertNotEquals(null, fdt.hashCode());
        System.assertNotEquals(null, fdt.toString());

        Datacloud.FindDuplicates finder = new Datacloud.FindDuplicates();
        System.assertNotEquals(null, finder);
        Datacloud.FindDuplicates finderClone = (Datacloud.FindDuplicates)finder.clone();
        System.assertNotEquals(finder, finderClone);
        Datacloud.FindDuplicatesByIds finderByIds = new Datacloud.FindDuplicatesByIds();
        System.assertNotEquals(null, finderByIds);
        Datacloud.FindDuplicatesByIds finderByIdsClone = (Datacloud.FindDuplicatesByIds)finderByIds.clone();
        System.assertNotEquals(finderByIds, finderByIdsClone);

        Datacloud.FindDuplicatesResult fdr = new Datacloud.FindDuplicatesResult();
        System.assertNotEquals(null, fdr);
        fdr.duplicateresults = new List<Datacloud.DuplicateResult>{dr};
        fdr.errors = new List<Database.Error>();
        fdr.success = true;
        System.assertEquals(1, fdr.duplicateresults.size());
        System.assertEquals(0, fdr.errors.size());
        System.assertEquals(true, fdr.success);
        System.assertEquals(0, fdr.getDuplicateResults().size());
        System.assertEquals(0, fdr.getErrors().size());
        System.assertEquals(true, fdr.isSuccess());
        fdr.success = false;
        System.assertEquals(false, fdr.isSuccess());
        System.assertEquals(true, fdr.equals(fdr));
        System.assertNotEquals(null, fdr.hashCode());
        System.assertNotEquals(null, fdr.toString());

        Datacloud.MatchRecord mr = new Datacloud.MatchRecord();
        System.assertNotEquals(null, mr);
    }
}
